#!/usr/bin/env python3
from __future__ import annotations

import base64
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def run(*args: str) -> None:
    subprocess.run(args, cwd=ROOT, check=True)


def write_b64(path: str, payload: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(payload))


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    if text.count(old) != 1:
        raise RuntimeError(f"{path}: expected exactly one replacement witness")
    target.write_text(text.replace(old, new), encoding="utf-8")


write_b64("crates/chess-core/src/see.rs", "")
write_b64("crates/chess-core/src/see_tests.rs", "")

replace_once(
    "crates/chess-core/src/lib.rs",
    "mod position;\nmod square;",
    "mod position;\nmod see;\nmod square;",
)
replace_once(
    "crates/chess-core/src/lib.rs",
    "pub use position::{\n    FenError, LegalMoveError, LegalMoveToken, LegalMoveTokenList, Position, PositionBuildError,\n    PositionInvariantError, PositionUndo,\n};\n",
    "pub use position::{\n    FenError, LegalMoveError, LegalMoveToken, LegalMoveTokenList, Position, PositionBuildError,\n    PositionInvariantError, PositionUndo,\n};\npub use see::{\n    static_exchange_evaluation, static_exchange_piece_value, static_exchange_semantic_checksum,\n    StaticExchangeClass, StaticExchangeError, StaticExchangeMoveStateError, StaticExchangeValue,\n    MAX_STATIC_EXCHANGE_PLIES, STATIC_EXCHANGE_POLICY_ID, STATIC_EXCHANGE_SCHEMA_VERSION,\n};\n",
)

run("cargo", "fmt", "--all")
run("cargo", "fmt", "--all", "--", "--check")
run(
    "cargo",
    "check",
    "--locked",
    "--workspace",
    "--all-targets",
    "--all-features",
)
run(
    "cargo",
    "clippy",
    "--locked",
    "--workspace",
    "--all-targets",
    "--all-features",
    "--",
    "-D",
    "warnings",
)
run(
    "cargo",
    "test",
    "--locked",
    "--workspace",
    "--all-targets",
    "--all-features",
)

Path(__file__).unlink()
run("git", "config", "user.name", "Phillip Chin")
run("git", "config", "user.email", "ekkus93@gmail.com")
run(
    "git",
    "add",
    "crates/chess-core/src/lib.rs",
    "crates/chess-core/src/see.rs",
    "crates/chess-core/src/see_tests.rs",
    "scripts/s2_4_core_stage.py",
)
run("git", "commit", "-m", "feat: implement allocation-free static exchange evaluation")
run("git", "push", "origin", "HEAD:master")
